"use client";

import { useState, useEffect } from "react";
import { initializeApp, getApps, FirebaseApp, getApp } from "firebase/app";
import {
  getAuth,
  Auth,
  signInAnonymously,
  onAuthStateChanged,
  User,
} from "firebase/auth";

interface FirebaseState {
  app: FirebaseApp | null;
  auth: Auth | null;
  userId: string | null;
  // isReadyがtrueになったら、Firebaseが認証状態（匿名 or 認証済み）を完全に解決したことを意味する
  isReady: boolean;
}

// Firebaseの初期化設定（process.envから読み込む）
const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
  // measurementId: process.env.NEXT_PUBLIC_FIREBASE_MEASUREMENT_ID, // 必要に応じて
};

export const useFirebaseInit = (): FirebaseState => {
  const [state, setState] = useState<FirebaseState>({
    app: null,
    auth: null,
    userId: null,
    isReady: false, // 初期状態は未準備
  });

  useEffect(() => {
    let unsubscribe: (() => void) | null = null;
    let authStateResolved = false;

    const initFirebase = async () => {
      try {
        // 1. AppとAuthサービスの初期化
        const app = !getApps().length
          ? initializeApp(firebaseConfig as any) // as any は型チェックを一時的に回避するため
          : getApp();
        const auth = getAuth(app);

        setState((s) => ({ ...s, app, auth }));

        // 2. 認証状態の監視
        // onAuthStateChangedは、ローカルストレージやCookieから認証状態を読み込み、
        // 状態が確定した時に最初に発火します。
        unsubscribe = onAuthStateChanged(auth, (user: User | null) => {
          // 初回発火時のみ isReady を true に設定
          if (!authStateResolved) {
            console.log(
              "[AuthInit] Initial state resolved. Setting isReady=true."
            );
            authStateResolved = true;
            setState((s) => ({
              ...s,
              userId: user?.uid ?? null,
              isReady: true,
            }));
          } else {
            // 状態変更時のユーザーID更新（リロード後のセッション復元ではない）
            setState((s) => ({ ...s, userId: user?.uid ?? null }));
          }
        });

        // 3. 匿名サインインを試みる（既存ユーザーがいなければ）
        // onAuthStateChangedが未認証を解決した後、匿名認証を試み、その結果をリスナーが拾う
        if (!auth.currentUser) {
          await signInAnonymously(auth);
          console.log("[AuthInit] Signed in anonymously or session restored.");
        }
      } catch (error) {
        console.error("[AuthInit] Firebase initialization failed:", error);

        // エラーが発生した場合も、isReadyをtrueにしてアプリのブロックを解除する
        if (!authStateResolved) {
          setState((s) => ({ ...s, isReady: true }));
        }
      }
    };

    initFirebase();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []); // 依存配列は空でOK

  return state;
};
